1	/**
2	 * @module features/tv-dashboard/ui/TvStoreColumn
3	 *
4	 * Coluna vertical de loja — redesign baseado em research de TV dashboards
5	 * (Bach et al. IEEE TVCG 2023 + practitioner evidence):
6	 * - Número de vendas é o sinal primário → domina o espaço visualmente
7	 * - Máximo 5 elementos por card para não causar cognitive overload
8	 * - 1 RAG status por card (não 15 células coloridas)
9	 * - Detalhe de perdas/marketing/estoque → drill-down /tv/loja/:id
10	 */
11	
12	import { useEffect, useRef, useState } from 'react';
13	import { Bike } from 'lucide-react';
14	import type { TvFreshnessLevel, TvPeriod, TvStoreData } from '../model/types';
15	import { formatCompactBRL, parseBrDateTime, parseIsoDateLocal } from '../model/tvMath';
16	import { TvDeltaChip, TvLiveIndicator, TvRankChip, TvStateChip } from './TvChips';
17	import {
18	  TvColumnBipLine,
19	  TvColumnMetaBar,
20	  TvColumnStockLine,
21	  TvUnitColumn,
22	} from './TvColumnParts';
23	import { formatTicketBRL, formatWeekdayDayMonth } from './tvFormat';
24	import { useCountUp } from './useCountUp';
25	
26	interface TvStoreColumnProps {
27	  store: TvStoreData;
28	  liveLevel: TvFreshnessLevel;
29	  period: TvPeriod;
30	  now: Date;
31	  rank?: number | null;
32	}
33	
34	/** Coluna de loja — canal Degust live ou Linx defasado. */
35	export function TvStoreColumn({ store, liveLevel, period, now, rank }: TvStoreColumnProps) {
36	  const { vendas, channel } = store;
37	  const isLive = channel === 'degust-live';
38	  const valorAnim = useCountUp(vendas?.valor ?? 0);
39	  const refDate = vendas ? parseIsoDateLocal(vendas.dataReferencia) : null;
40	
41	  // Flash dourado ao atualizar o valor de venda
42	  const prevValueRef = useRef(vendas?.valor);
43	  const [flashing, setFlashing] = useState(false);
44	  const flashKeyRef = useRef(0);
45	  useEffect(() => {
46	    if (
47	      vendas?.valor != null &&
48	      prevValueRef.current != null &&
49	      vendas.valor !== prevValueRef.current
50	    ) {
51	      flashKeyRef.current += 1;
52	      setFlashing(true);
53	      const t = window.setTimeout(() => setFlashing(false), 450);
54	      prevValueRef.current = vendas.valor;
55	      return () => window.clearTimeout(t);
56	    }
57	    prevValueRef.current = vendas?.valor;
58	  }, [vendas?.valor]);
59	
60	  // Linha de status: fonte + horário de atualização
61	  const updateTime = isLive ? parseBrDateTime(vendas?.atualizadoEm) : null;
62	  const laggedLabel = !isLive && refDate ? formatWeekdayDayMonth(refDate) : null;
63	
64	  const showRank = rank != null && rank >= 1 && rank <= 3;
65	
66	  return (
67	    <TvUnitColumn lojaId={store.lojaId} nome={store.nome} rag={store.rag} testId="tv-store-column">
68	
69	      {/* Header: nome + chips de status */}
70	      <div className="flex items-start justify-between gap-2">
71	        <h2 className="min-w-0 font-momma text-sm font-semibold leading-tight text-[#5F6F63] truncate">
72	          {store.nome.replace(/^Momma\s+/i, '')}
73	        </h2>
74	        <div className="flex shrink-0 items-center gap-1">
75	          {showRank && <TvRankChip rank={rank as 1 | 2 | 3} />}
76	          <TvStateChip rag={store.rag} />
77	        </div>
78	      </div>
79	
80	      {/* Número de vendas + setinhas inline — exatamente como na v2 */}
81	      <div className="mt-2 flex flex-wrap items-end gap-x-2 gap-y-1">
82	        <span
83	          key={flashing ? `flash-${flashKeyRef.current}` : 'static'}
84	          className={`font-momma text-3xl font-bold leading-none tabular-nums sm:text-4xl ${
85	            vendas ? 'text-[#2D362E]' : 'text-[#9ca3af]'
86	          }${flashing ? ' tv-value-flash' : ''}`}
87	          data-testid="tv-store-sales"
88	        >
89	          {vendas ? formatCompactBRL(valorAnim) : '—'}
90	        </span>
91	        {store.deltaOntem != null && (
92	          <TvDeltaChip delta={store.deltaOntem} label={isLive ? 'ontem' : 'dia ant.'} size="card" />
93	        )}
94	        {store.deltaSemana != null && period === 'week' && (
95	          <TvDeltaChip delta={store.deltaSemana} label="sem. ant." size="card" />
96	        )}
97	      </div>
98	
99	      {/* R1: quebra Loja × Delivery (só BSB Shopping, período "hoje") —
100	          o número principal acima segue sendo o TOTAL oficial */}
101	      {store.deliverySplit && (
102	        <p
103	          className="mt-1 flex flex-wrap items-center gap-x-1.5 gap-y-0 text-xs tabular-nums text-[#7C887E]"
104	          data-testid="tv-delivery-split"
105	        >
106	          <span className="whitespace-nowrap">
107	            Loja{' '}
108	            <span className="font-medium text-[#5F6F63]">
109	              {formatCompactBRL(store.deliverySplit.balcao)}
110	            </span>
111	          </span>
112	          <span aria-hidden>·</span>
113	          <span className="inline-flex items-center gap-1 whitespace-nowrap">
114	            <Bike className="h-3 w-3 shrink-0 text-[#57715B]" aria-hidden />
115	            Delivery{' '}
116	            <span className="font-medium text-[#5F6F63]">
117	              {formatCompactBRL(store.deliverySplit.delivery)}
118	            </span>
119	          </span>
120	        </p>
121	      )}
122	
123	      {/* Status de fonte — compacto, sem "ao vivo" como texto */}
124	      <p className="mt-1 flex items-center gap-1.5 text-xs text-[#9ca3af]">
125	        <TvLiveIndicator channel={channel} liveLevel={liveLevel} />
126	        {isLive
127	          ? updateTime
128	            ? `${updateTime.getHours().toString().padStart(2, '0')}:${updateTime.getMinutes().toString().padStart(2, '0')}`
129	            : 'hoje'
130	          : laggedLabel ?? 'sem dados'}
131	      </p>
132	
133	      {/* Barra de meta */}
134	      <TvColumnMetaBar pctMetaProRata={store.pctMeta} metaDia={store.metaDia} now={now} />
135	
136	      {/* Nº de vendas + R$/venda — cada parte non-breaking para não cortar */}
137	      {isLive && (vendas?.cupons != null || vendas?.ticketMedio != null) && (
138	        <div className="mt-2 flex flex-wrap items-baseline gap-x-1.5 gap-y-0 text-xs tabular-nums text-[#7C887E]">
139	          {vendas?.cupons != null && (
140	            <span className="whitespace-nowrap font-medium">
141	              {vendas.cupons} vendas
142	            </span>
143	          )}
144	          {vendas?.ticketMedio != null && vendas.ticketMedio > 0 && (
145	            <span className="whitespace-nowrap">
146	              {vendas.cupons != null && '· '}
147	              <span className="font-medium">{formatTicketBRL(vendas.ticketMedio)}</span>
148	              <span>/venda</span>
149	            </span>
150	          )}
151	        </div>
152	      )}
153	
154	      {/* Bip + Status de estoque — 1 linha para cada */}
155	      <div className="mt-auto pt-3 space-y-1">
156	        <TvColumnBipLine ultimaBipagem={store.movimentacao.ultimaBipagem} now={now} />
157	        <TvColumnStockLine estoque={store.estoque} />
158	      </div>
159	    </TvUnitColumn>
160	  );
161	}
