294	        <div
295	          className={`absolute inset-y-0 left-0 rounded-full transition-[width] [transition-duration:600ms] ease-out motion-reduce:transition-none ${BAR_FILL_CLS[color]}`}
296	          style={{ width: `${clampPct(fillPct)}%` }}
