/** Cor do % da semana: emerald quando batida; senão mesma régua da barra. */
const WEEKLY_PCT_CLS: Record<TvBarColor, string> = {
  sage: 'text-[#57715B]',
  amber: 'text-amber-600',
  red: 'text-red-600',
};

/**
 * Linha SECUNDÁRIA de meta semanal do card: label "SEMANA" + % em destaque
 * (cor pela mesma régua da barra diária; emerald quando ≥ 100%) + valores
 * compactos "R$ X / R$ Y" + mini barra de progresso ({@link TvMetaBar} mini,
 * sem tick de esperado — semana não tem pró-rata intradiário).
 */
function TvStoreWeeklyGoalLine({
  weeklyGoal,
  now,
}: {
  weeklyGoal: NonNullable<TvStoreData['weeklyGoal']>;
  now: Date;
}) {
  const { target, achieved, pct } = weeklyGoal;
  const beaten = pct != null && pct >= 100;
  const barColor: TvBarColor = beaten
    ? 'sage'
    : metaBarColorFromRatio(pct != null ? pct / 100 : null, now);
  const pctCls = beaten ? 'text-emerald-600' : WEEKLY_PCT_CLS[barColor];

  return (
    <div className="mt-2" data-testid="tv-weekly-goal">
      <div className="flex flex-wrap items-baseline justify-between gap-x-2 gap-y-0.5">
        <span className="font-momma text-[10px] font-semibold uppercase tracking-wider text-[#7C887E]">
          SEMANA
        </span>
        <span className="min-w-0 truncate text-right font-momma text-[10px] tabular-nums text-[#9ca3af]">
          <span
            className={`text-xs font-bold tabular-nums ${pctCls}`}
            data-testid="tv-weekly-goal-pct"
          >
            {pct != null ? `${Math.round(pct)}%` : '—'}
          </span>{' '}
          {formatCompactBRL(achieved)} / {formatCompactBRL(target)}
        </span>
      </div>
      <div className="mt-1">
        <TvMetaBar fillPct={pct} expectedPct={null} color={barColor} size="mini" />
      </div>
    </div>
  );
}

describe('TvStoreColumn — meta semanal (weeklyGoal)', () => {
  it('com weeklyGoal: label SEMANA + % + valores compactos + mini barra', () => {
    renderColumn({
      ...baseStore,
      weeklyGoal: { target: 374_500, achieved: 103_400, pct: 27.6 },
    });
    const block = screen.getByTestId('tv-weekly-goal');
    expect(block).toHaveTextContent('SEMANA');
    expect(screen.getByTestId('tv-weekly-goal-pct')).toHaveTextContent('28%');
    expect(block).toHaveTextContent('R$ 103,4k / R$ 374,5k');
    expect(screen.getByTestId('tv-meta-bar')).toBeInTheDocument();
  });

  it('meta batida (pct ≥ 100): % em emerald', () => {
    renderColumn({
      ...baseStore,
      weeklyGoal: { target: 10_000, achieved: 11_500, pct: 115 },
    });
    const pct = screen.getByTestId('tv-weekly-goal-pct');
    expect(pct).toHaveTextContent('115%');
    expect(pct.className).toContain('text-emerald-600');
  });

  it('weeklyGoal null: nada da semana no DOM', () => {
    renderColumn({ ...baseStore, weeklyGoal: null });
    expect(screen.queryByTestId('tv-weekly-goal')).not.toBeInTheDocument();
    expect(screen.queryByText('SEMANA')).not.toBeInTheDocument();
  });
});

